// Package httpapi serves the contract in api/openapi.yaml (ATLAS.md §14). api.gen.go is generated by
// oapi-codegen (strict server on the stdlib ServeMux); this package adds the handlers and error mapping.
package httpapi

import (
	"context"
	"net/http"
	"time"
)

// probeTimeout bounds each readiness check so /readyz answers even when a dependency hangs.
const probeTimeout = 2 * time.Second

const statusOK = "ok"

// Check is one dependency probed by /readyz.
type Check struct {
	Name  string
	Probe func(context.Context) error
}

// Server implements the strict server interface. Operations not built yet are in unimplemented.go.
type Server struct {
	Checks        []Check
	Version       string
	SchemaVersion int64
	Accounts      Accounts
	Audit         AuditLog
	Sources       SourceAdmin
	Documents     DocumentLibrary
	Taxonomy      Taxonomy
	Idempotency   IdempotencyStore
	Answers       Answers
	Licenses      LicenseSource
	Graph         GraphView
	Panel         PanelSource
	Deployment    Deployment
}

// NewHandler returns the HTTP handler for the whole contract.
func NewHandler(s *Server) http.Handler {
	reqs, err := requirementsFromSpec()
	if err != nil {
		panic(err) // the embedded contract is wrong: a build-time fault, caught by the tests
	}
	strict := NewStrictHandlerWithOptions(s, []StrictMiddlewareFunc{s.authenticate(reqs)}, StrictHTTPServerOptions{
		RequestErrorHandlerFunc:  handleRequestError,
		ResponseErrorHandlerFunc: handleResponseError,
	})
	return sameOrigin(s.idempotent(HandlerWithOptions(strict, StdHTTPServerOptions{ErrorHandlerFunc: handleRequestError})))
}

// GetHealthz answers as long as the process runs.
func (s *Server) GetHealthz(context.Context, GetHealthzRequestObject) (GetHealthzResponseObject, error) {
	return GetHealthz200JSONResponse{Status: HealthStatusOk}, nil
}

// GetReadyz probes every dependency and reports each one.
func (s *Server) GetReadyz(ctx context.Context, _ GetReadyzRequestObject) (GetReadyzResponseObject, error) {
	results, healthy := s.probeAll(ctx)
	if !healthy {
		return GetReadyz503JSONResponse{Status: ReadinessStatusDegraded, Checks: results}, nil
	}
	return GetReadyz200JSONResponse{Status: ReadinessStatusOk, Checks: results}, nil
}

func (s *Server) probeAll(ctx context.Context) (map[string]string, bool) {
	results := make(map[string]string, len(s.Checks))
	healthy := true
	for _, c := range s.Checks {
		results[c.Name] = statusOK
		if err := probe(ctx, c); err != nil {
			results[c.Name], healthy = err.Error(), false
		}
	}
	return results, healthy
}

func probe(ctx context.Context, c Check) error {
	ctx, cancel := context.WithTimeout(ctx, probeTimeout)
	defer cancel()
	return c.Probe(ctx)
}

// GetVersion reports the build and the schema version this binary needs.
func (s *Server) GetVersion(context.Context, GetVersionRequestObject) (GetVersionResponseObject, error) {
	return GetVersion200JSONResponse{Version: s.Version, Schema: s.SchemaVersion}, nil
}
